TEMPLATE_NAMES = {'outer.py.in', 'qga.py.in', 'provision.py.in', 'Dockerfile.in'}
MAX_SOURCE_BYTES = 1048576


class TemplateError(ValueError):
    """An absent/drifted source or unsupported template contract was refused."""


@dataclass(frozen=True)
class Generation:
    files: dict[str, bytes]
    plan: dict


def canonical(value):
    return (json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=True) + '\n').encode('ascii')


def digest(data):
    return hashlib.sha256(data).hexdigest()


def read_source(path, expected):
    """Read a bounded regular source, refusing linked parents and partial reads."""
    try:
        if path != path.resolve(strict=True):
            raise TemplateError('source path alias refused: ' + path.name)
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        with os.fdopen(fd, 'rb') as stream:
            info = os.fstat(stream.fileno())
            if not stat.S_ISREG(info.st_mode) or not 0 < info.st_size <= MAX_SOURCE_BYTES:
                raise TemplateError('source type/size refused: ' + path.name)
            raw = stream.read(MAX_SOURCE_BYTES + 1)
            after = os.fstat(stream.fileno())
            if (info.st_dev, info.st_ino, info.st_size, info.st_mtime_ns, info.st_ctime_ns) != (
                    after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns, after.st_ctime_ns):
                raise TemplateError('source changed during read: ' + path.name)
    except OSError:
        raise TemplateError('source absent/inaccessible: ' + path.name) from None
    if len(raw) != info.st_size or digest(raw) != expected:
        raise TemplateError('source hash drift: ' + path.name)
    return raw.decode('utf-8')


def sources(root):
    directory = root / 'public_templates'
    try:
        if {path.name for path in directory.iterdir()} != TEMPLATE_NAMES:
            raise TemplateError('exact finite template set required')
    except OSError:
        raise TemplateError('template directory absent/inaccessible') from None
    result = {name: read_source(root / name, expected) for name, expected in CONTRACT_HASHES.items()}
    result.update({name: read_source(directory / name, expected)
                   for name, expected in TEMPLATE_HASHES.items()})
    return result


def literal(source, name):
    """Use maintained constant values without importing executable backend code."""
    for node in ast.parse(source).body:
        if isinstance(node, ast.Assign) and any(isinstance(t, ast.Name) and t.id == name for t in node.targets):
            return ast.literal_eval(node.value)
    raise TemplateError('maintained literal missing: ' + name)


def package(item):
    leaf = unquote(urlsplit(item.url).path.rsplit('/', 1)[-1])
    parts = leaf.split('_')
    if len(parts) != 3 or not re.fullmatch('[a-z0-9][a-z0-9+.-]*', parts[0]):
        raise TemplateError('package filename refused')
    return {'id': item.id, 'name': parts[0], 'version': item.version,
            'bytes': item.bytes, 'sha256': item.sha256}


def substitute(text, values):
    used = set(re.findall(r'@@([A-Z_0-9]+)@@', text))
    if used != set(values):
        raise TemplateError('finite template substitutions changed')
    for name, value in values.items():
        text = text.replace('@@' + name + '@@', value)
    if '@@' in text:
        raise TemplateError('unresolved template input')
    return text


def copy_inputs(dockerfile, available):
    """Resolve every COPY leaf; reject ADD, globs, directories and hidden inputs."""
    copies = []
    for line in dockerfile.splitlines():
        parts = shlex.split(line, comments=True)
        if not parts or parts[0].upper() not in ('COPY', 'ADD'):
            continue
        if parts[0].upper() != 'COPY' or len(parts) < 3:
            raise TemplateError('finite COPY required')
        for name in parts[1:-1]:
            if name not in available or name in copies:
                raise TemplateError('COPY source absent/duplicate: ' + name)
            copies.append(name)
    if set(copies) != set(available):
        raise TemplateError('COPY closure incomplete')
    return copies


def _render(descriptor, source, *, profile=None):
    artifacts = descriptor.artifacts
    by_kind = {kind: [item for item in artifacts if item.kind == kind]
               for kind in ('base', 'runner-archive', 'runtime-image', 'toolchain', 'guest-package')}
    base, = by_kind['base']
    archive, = by_kind['runner-archive']
    image, = by_kind['runtime-image']
    if (archive.sha256 != literal(source['runner_setup.py'], 'ARCHIVE_SHA')
            or archive.version != '2.336.0' or archive.url.rsplit('/', 1)[-1] != literal(source['runner_setup.py'], 'ARCHIVE')):
        raise TemplateError('maintained installer archive identity mismatch')
    tools = [package(item) for item in by_kind['toolchain']]
    guest = [package(item) for item in by_kind['guest-package']]
    if len({p['name'] for p in tools}) != len(tools) or len({p['name'] for p in guest}) != len(guest):
        raise TemplateError('duplicate package name')
    tool_paths = ['toolchain/' + row['id'] + '.deb' for row in tools]
    install_options = '-y --no-download'
    if profile is not None and profile['name'] != 'historical':
        copies = 'COPY ' + ' '.join(tool_paths) + ' /opt/public-toolchain/'
        # APT must acquire these local files into its cache; sources stay disabled.
        install_options = '-y'
    else:
        copies = '\n'.join('COPY ' + path + ' /opt/public-toolchain/' + Path(path).name for path in tool_paths)
    checks = '\n'.join(row['sha256'] + '  /opt/public-toolchain/' + row['id'] + '.deb' for row in tools) + '\n'
    # JSON exec form keeps pins inert and does not depend on build-host shell.
    shell = ('printf %s ' + shlex.quote(checks) + ' > /tmp/public-toolchain.sha256; sha256sum -c /tmp/public-toolchain.sha256; '
             'DEBIAN_FRONTEND=noninteractive apt-get ' + install_options + ' --no-install-recommends '
             '-o Dir::Etc::sourcelist=/dev/null -o Dir::Etc::sourceparts=- install '
             + ' '.join('/opt/public-toolchain/' + row['id'] + '.deb' for row in tools)
             + '; ' + '; '.join('test "$(dpkg-query -W -f=\'${Version}\' ' + shlex.quote(row['name'])
                                 + ')" = ' + shlex.quote(row['version']) for row in tools)
             + '; rm -rf /opt/public-toolchain; rm /tmp/public-toolchain.sha256')
    alpine = literal(source['vm_backend.py'], 'ALPINE_SHA') if profile is None else profile['alpine_sha256']
    texts = {
        'outer.py': substitute(source['outer.py.in'], {'BASE_SHA256': base.sha256}),
        'qga.py': substitute(source['qga.py.in'], {}),
        'Dockerfile': substitute(source['Dockerfile.in'], {
            'IMAGE_SHA256': image.sha256, 'RECIPE_SHA256': descriptor.sha256,
            'TOOL_COPIES': copies, 'TOOL_INSTALL': json.dumps(['/bin/sh', '-eu', '-c', shell])}),
        'iso/provision.py': substitute(source['provision.py.in'], {
            'GUEST_PACKAGES': repr(guest), 'ARCHIVE_SHA256': archive.sha256, 'ALPINE_SHA256': alpine}),
        'base.sha256': base.sha256 + '\n',
        'iso/expected.manifest': ''.join(row['name'] + ' ' + row['version'] + '\n'
                                         for row in sorted(guest, key=lambda row: row['name'])),
        'iso/meta-data': 'instance-id: vi-public-' + descriptor.sha256 + '\nlocal-hostname: owned-local-vm\n',
    }
    config = {'users': [], 'disable_root': True, 'ssh_pwauth': False, 'ssh_deletekeys': True,
              'ssh_genkeytypes': [], 'ssh_import_id': [], 'allow_public_ssh_keys': False,
              'package_update': False, 'package_upgrade': False,
              'growpart': {'mode': 'auto', 'devices': ['/'], 'ignore_growroot_disabled': False},
              'resize_rootfs': True,
              'runcmd': [['mount', '-o', 'ro,nosuid,nodev,noexec', '/dev/sr0', '/mnt'],
                         ['/usr/bin/python3', '/mnt/provision.py']]}
    texts['iso/user-data'] = '#cloud-config\n' + canonical(config).decode('ascii')
    for name, text in texts.items():
        if name.endswith('.py'):
            ast.parse(text, filename=name)
    available = ['base.qcow2', 'base.sha256', 'outer.py', 'qga.py', 'seed.iso', *tool_paths]
    copy_plan = copy_inputs(texts['Dockerfile'], available)
    dependencies = {'base.qcow2': {'artifact': base.id, 'sha256': base.sha256},
                    'seed.iso': {'kind': 'later-deterministic-iso', 'qualified': False},
                    'iso/install-runner.py': {'kind': 'runner_setup.installer_for', 'qualified': False},
                    'iso/' + literal(source['runner_setup.py'], 'ARCHIVE'): {'artifact': archive.id, 'sha256': archive.sha256},
                    'iso/native_policy.py': {'source': 'native_policy.py', 'sha256': CONTRACT_HASHES['native_policy.py']},
                    'iso/native-inputs.json': {'source': 'native-inputs.json', 'sha256': CONTRACT_HASHES['native-inputs.json']},
                    'iso/alpine.tar': {'kind': 'required-lifecycle-fixture', 'sha256': alpine,
                                       'image': literal(source['vm_backend.py'], 'ALPINE') if profile is None else profile['alpine_image'],
                                       'public_origin_accepted': profile is not None and profile['name'] != 'historical'}}
    if profile is not None:
        dependencies['iso/alpine.tar'].update(bytes=profile['alpine_bytes'],
                                            manifest=profile['alpine_manifest'],
                                            origin=profile['alpine_origin'])
    for rows, prefix in ((tools, 'toolchain/'), (guest, 'iso/packages/')):
        dependencies.update({prefix + row['id'] + '.deb': {'artifact': row['id'], 'sha256': row['sha256'],
                                                         'bytes': row['bytes']} for row in rows})
    files = {name: texts[name].encode('utf-8') for name in FILES}
    plan = {'schema': 1, 'recipe_sha256': descriptor.sha256,
            'inputs': {item.id: {'kind': item.kind, 'sha256': item.sha256, 'bytes': item.bytes,
                                  'url': item.url, 'dependencies': list(item.dependencies)} for item in artifacts}, 'generated': {name: digest(data) for name, data in files.items()},
            'contracts': dict(CONTRACT_HASHES), 'templates': dict(TEMPLATE_HASHES),
            'docker_copy_inputs': copy_plan, 'dependencies': dict(sorted(dependencies.items())),
            'capacity_coupling': {'api': 'runner_setup.capacity_sources',
                                  'requires_new_base_budget_identity': True,
                                  'helpers': ['owned_overlay.py', 'baseline_budget.py', 'guest_capacity.py',
                                              'failure_observation.py', 'iso/guest_capacity.py']},
            'pending': ['lifecycle-fixture-public-provenance-and-bytes', 'reviewed-new-base-helper-budget',
                        'bank-materialization-and-iso', 'namespace', 'causal-runtime-qualification'],
            'runtime_qualified': False, 'execution_allowed': False}
    if profile is not None:
        plan['selection'] = dict(profile)
    return Generation(files, plan)


def generate(raw, selected, *, expected_sha256, source_root=ROOT, selection=None, fixture=None):
    """Verify all sources and explicit actual inputs, then return eight byte strings.

    Missing templates and source drift fail before any artifact read. No output
    directory, copying, extraction, subprocess or network is part of this API.
    An explicit new selection rechecks the separately accepted fixture bytes.
    Unselected calls retain the historical unbound source-proposal contract.
    Generation never grants bank, ISO or runtime qualification.
    """
    source = sources(Path(source_root))
    descriptor = public_recipe.parse_descriptor(raw)
    profile = None
    if selection is not None:
        profiles = {literal(source['public_recipe_selection.py'], name)['name']:
                    literal(source['public_recipe_selection.py'], name) for name in ('HISTORICAL', 'PUBLIC')}
        if type(selection) is not str or selection not in profiles:
            raise TemplateError('explicit reviewed recipe selection required')
        profile = profiles[selection]
        base, = (item for item in descriptor.artifacts if item.kind == 'base')
        if (base.sha256 != profile['base_sha256'] or base.bytes != profile['base_bytes']
                or (profile['recipe_sha256'] is not None and descriptor.sha256 != profile['recipe_sha256'])):
            raise TemplateError('recipe selection/base identity mismatch')
    if profile is not None and selection != 'historical':
        if type(fixture) is not public_recipe.RetainedFile or fixture.origin != profile['alpine_origin']:
            raise TemplateError('explicit accepted lifecycle fixture selection required')
        artifact = public_recipe.Artifact(id='alpine', kind='fixture', version='accepted-c24',
                                         architecture='amd64', publisher='docker-library',
                                         url=profile['alpine_origin'], sha256=profile['alpine_sha256'],
                                         bytes=profile['alpine_bytes'], dependencies=())
        try:
            public_recipe._read_retained(fixture.path, artifact)
        except OSError:
            raise TemplateError('lifecycle fixture absent/inaccessible') from None
    elif fixture is not None:
        raise TemplateError('fixture requires explicit new recipe selection')
    receipt = public_recipe.verify_retained(raw, selected, expected_sha256=expected_sha256)
    result = _render(descriptor, source, profile=profile)
    if receipt['recipe_sha256'] != descriptor.sha256:
        raise TemplateError('verified input receipt drift')
    return result
